import {previewAPI,exportPreview} from './preview.mjs';
import {gmailSettings,gmailAction,gmailSubmit,gmailInput} from './gmail.mjs';
import {resumeSection,lettersPage,libraryInput,uploadFiles,libraryAction,librarySubmit,letterSuggestions} from './library.mjs';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escape;
const shapes={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/><path d="M20 2v4M18 4h4"/>',saved:'<path d="M6 4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v17l-6-4-6 4Z"/>',applications:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v3M3 12a22 22 0 0 0 18 0M12 11v4"/>',insights:'<path d="M4 20V10m8 10V4m8 16v-8M2 21h20"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',refresh:'<path d="M20 7V3l-3 3A8 8 0 1 0 3 13M20 3h-5M4 17v4l3-3a8 8 0 0 0 14-7M4 21h5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7m0-7L10 14M11 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',location:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',money:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 9v6m14-6v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 2 8 4v6c0 6-8 10-8 10S4 18 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/><circle cx="9" cy="7" r="2"/><circle cx="15" cy="12" r="2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',logout:'<path d="M9 3H4v18h5m5-15 6 6-6 6M8 12h12"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',file:'<path d="M14 2H5v20h14V7Zm0 0v6h5M8 12h8M8 16h8"/>',thumb:'<path d="M7 10v11H3V10Zm0 0 5-8c2 0 3 2 2 5l-1 3h6a2 2 0 0 1 2 2l-2 7a2 2 0 0 1-2 2H7"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
const icon=(name,extra='')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}>${shapes[name]??shapes.spark}</svg>`;
const statuses=['Applied','In Review','Recruiter Contact','Interviewing','Assessment','Offer','Rejected','Withdrawn','No Response'];
const routes=[['overview','Overview','overview'],['discover','Discover','discover'],['wildcards','Wildcards','spark'],['saved','Saved Jobs','saved'],['applications','Applications','applications'],['insights','Insights','insights'],['profile','Profile & Résumé','profile'],['letters','Cover Letters','mail'],['settings','Settings','settings']];
let data=null,session=null,route=location.hash.slice(1)||'overview',theme=localStorage.getItem('careeros-theme')??(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
let search='',tab='All',advanced=false,sort='recommended',limit=24,appStatus='All',appSort='newest';
let filters={company:'',location:'',mode:'All',score:0,minSalary:0,includeUnknown:true,closed:false,dismissed:false,source:'',date:''};
let appFilters={company:'',location:'',source:'',from:'',to:''};let polling=null,toastTimer=null;
const root=$('#app'),modal=$('#modal');
const formatDate=(s,options={month:'short',day:'numeric'})=>s?new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString('en-US',options):'Not published';
const ago=s=>{if(!s)return'Never';const n=Math.max(0,Date.now()-Date.parse(s));return n<60000?'Just now':n<3600000?`${Math.floor(n/60000)}m ago`:n<86400000?`${Math.floor(n/3600000)}h ago`:`${Math.floor(n/86400000)}d ago`;};
const salary=j=>j.salaryMin!==null||j.salaryMax!==null?`${j.currency??''} ${j.salaryMin!==null?Math.round(j.salaryMin/1000)+'k':'—'}${j.salaryMax!==null?' – '+Math.round(j.salaryMax/1000)+'k':''} / year`:'Salary not published';
const statusClass=s=>['Offer','Interviewing'].includes(s)?'green':s==='Rejected'?'red':s==='Assessment'?'purple':s==='Recruiter Contact'?'blue':s==='In Review'?'amber':'';
const badge=s=>`<span class="badge ${statusClass(s)}">${e(s)}</span>`;
const categoryBadge=c=>`<span class="badge ${c==='Wildcard'?'purple':c==='Core'?'green':''}">${c==='Wildcard'?'✦ ':''}${e(c)}</span>`;
const logo=company=>`<div class="company-logo" aria-hidden="true">${e(company.split(/\s+/).map(w=>w[0]).slice(0,2).join(''))}</div>`;
const button=(text,action,klass='',ico='')=>`<button class="button ${klass}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;
const empty=(ico,title,text,action='',compact=false)=>`<div class="empty ${compact?'compact':''}"><div class="empty-icon">${icon(ico)}</div><h3>${e(title)}</h3><p>${e(text)}</p>${action?`<div class="button-row">${action}</div>`:''}</div>`;
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',5000);}
async function api(path,method='GET',payload){return previewAPI(path,method,payload);}
async function load(render=true){data=await api('bootstrap');if(render)renderApp();managePolling();}
function managePolling(){if((data?.discovery.running||data?.integrations?.gmail?.running)&&!polling)polling=setInterval(async()=>{try{await load(!modal.open);}catch{clearInterval(polling);polling=null;}},2500);if(!data?.discovery.running&&!data?.integrations?.gmail?.running&&polling){clearInterval(polling);polling=null;}}
async function init(){document.documentElement.dataset.theme=theme;try{session=await api('session');if(session.authenticated){await load();try{const sync=await api("sync","POST",{reason:"open"});if(sync.discovery){data.discovery=sync.discovery;if(sync.gmail)data.integrations.gmail=sync.gmail;renderApp();managePolling();}}catch(error){toast("Workspace opened, but discovery could not refresh: "+error.message,true);}}else renderAuth();}catch(err){root.innerHTML=`<main id="main" class="initial-loading"><div class="brand-mark">✦</div><h1>Workspace unavailable</h1><p>${e(err.message)}</p>${button('Try again','retry','primary')}</main>`;}}
function navigate(path){route=path||'overview';if(!routes.some(r=>r[0]===route))route='overview';search='';tab='All';limit=24;advanced=false;history.pushState({},'','#'+route);renderApp();window.scrollTo(0,0);}
function renderAuth(){document.documentElement.dataset.careerosReady='true';if(modal.open)modal.close();const setup=!session.ownerExists;root.innerHTML=`<div class="auth-layout"><section class="auth-story"><a class="brand" href="#overview"><div class="brand-mark">✦</div><div>Career<span>OS</span></div></a><h1>Your next chapter.<br>A clearer perspective.</h1><p>A private workspace to discover unexpected opportunities, make thoughtful moves, and see your career journey in one place.</p><div class="auth-features"><span>${icon('shield')} Private by design</span><span>${icon('target')} Built around your interests</span></div></section><main id="main" class="auth-main"><div class="auth-card"><div class="eyebrow">YOUR CAREER, IN FOCUS</div><h2>${setup?'Make this space yours.':'Welcome back.'}</h2><p>${setup?'Create your private owner account. No résumé or external account is required.':'Sign in to your personal career workspace.'}</p>${setup&&!session.setupAllowed?'<div class="notice warn">Run npm run setup on the server to create your owner account.</div>':`<form id="auth-form" data-setup="${setup}"><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="username" placeholder="you@example.com" required maxlength="250"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="${setup?14:1}" maxlength="256" placeholder="${setup?'At least 14 characters':'Your password'}" required></div><p class="form-error" role="alert"></p><button class="button primary" type="submit">${setup?'Create my workspace':'Sign in'} ${icon('arrow')}</button></form>`}<div class="auth-note">${icon('shield')} The private backend is not connected to this preview. Résumé and cover-letter uploads stay private. Gmail is optional and not connected.</div><p class="auth-foot">A little more clarity. A lot more possibility.</p></div></main></div>`;}
function metrics(){const apps=data.applications;const count=s=>apps.filter(a=>a.status===s).length;const responses=apps.filter(a=>a.lastResponseAt||['In Review','Recruiter Contact','Interviewing','Assessment','Offer','Rejected'].includes(a.status)).length;return {total:apps.length,count,responses,rate:apps.length?Math.round(responses/apps.length*100):0,interviews:count('Interviewing'),offers:count('Offer'),follow:apps.filter(a=>a.status==='No Response').length};}
function renderApp(){
 if(!data)return;document.documentElement.dataset.careerosReady='true';
 const active=routes.find(r=>r[0]===route)??routes[0];route=active[0];const m=metrics();const fresh=data.jobs.filter(j=>j.availability==='Open'&&!j.dismissed);const saved=data.jobs.filter(j=>j.saved).length;
 root.innerHTML=`<div class="layout"><button class="mobile-overlay" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#overview" data-nav="overview"><div class="brand-mark">✦</div><div>Career<span>OS</span></div></a><div class="nav-label">YOUR WORKSPACE</div><nav class="nav">${routes.slice(0,6).map(([r,label,ico])=>`<a href="#${r}" data-nav="${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(ico)} ${label}${['discover','saved','applications'].includes(r)?`<span class="nav-count">${r==='discover'?fresh.length:r==='saved'?saved:m.total}</span>`:''}${r==='wildcards'?'<span class="nav-count">✦</span>':''}</a>`).join('')}</nav><div class="nav-label">PERSONALIZE</div><nav class="nav">${routes.slice(6).map(([r,label,ico])=>`<a href="#${r}" data-nav="${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(ico)} ${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-card"><strong><span class="dot"></span>Interface preview</strong><p>Thoughtful discovery.<br>Everything in perspective.</p></div><div class="account"><div class="avatar">${e(data.profile.email.slice(0,2).toUpperCase())}</div><div class="account-info"><strong>Preview workspace</strong><small>${e(data.profile.email)}</small></div><button class="icon-button" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${active[1]}</strong></div><div class="top-actions"><span class="date-label">${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</span><button class="icon-button search-launch" data-action="search" aria-label="Search opportunities">${icon('search')}</button><button class="icon-button" data-action="theme" aria-label="Switch to ${theme==='light'?'dark':'light'} mode">${icon(theme==='light'?'moon':'sun')}</button></div></header>${data.discovery.running?'<div class="loading-line" role="status" aria-label="Refreshing job sources"></div>':''}<main id="main" class="content route-enter">${route==='overview'?overview():route==='discover'||route==='wildcards'||route==='saved'?discover():route==='applications'?applications():route==='insights'?insights():route==='profile'?profile():route==='letters'?lettersPage(libraryContext()):settings()}</main></div></div>`;
}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>${actions}</div>`;}
function metricCards(){const m=metrics();return `<div class="metric-grid"><article class="metric"><div class="metric-top">Applications ${icon('applications')}</div><div class="metric-value">${m.total}</div><div class="metric-foot">Your journey so far</div></article><article class="metric"><div class="metric-top">Response rate ${icon('mail')}</div><div class="metric-value">${m.total?m.rate+'%':'—'}</div><div class="metric-foot">${m.total?m.responses+' applications with a response':'Appears after your first application'}</div></article><article class="metric"><div class="metric-top">Interviewing ${icon('profile')}</div><div class="metric-value">${m.interviews}</div><div class="metric-foot">${m.offers?`<span class="green">${m.offers} offer${m.offers===1?'':'s'} received</span>`:'Active interview processes'}</div></article><article class="metric"><div class="metric-top">Awaiting follow-up ${icon('clock')}</div><div class="metric-value">${m.follow}</div><div class="metric-foot">30+ days without a response</div></article></div>`;}
function overview(){const rec=data.jobs.filter(j=>j.availability==='Open'&&!j.dismissed).slice(0,3);return `${heading('A LITTLE CLARITY FOR YOUR NEXT MOVE','Your next chapter starts here.','Discover with intention. Keep the whole journey in view.',button(data.discovery.running?'Refreshing…':'Refresh discovery','refresh','', 'refresh'))}<section class="hero"><div class="hero-copy"><div class="eyebrow">BEYOND THE EXPECTED</div><h2>There’s more than one way<br>to make your next move.</h2><p>From platform integrity to protective intelligence, explore opportunities connected by the work that matters to you.</p><div class="button-row"><a href="#discover" data-nav="discover" class="button primary">Explore opportunities ${icon('arrow')}</a><a href="#wildcards" data-nav="wildcards" class="button subtle">Meet your wildcards ${icon('spark')}</a></div></div><div class="radar" aria-hidden="true"><div class="radar-ring"></div><div class="radar-cross"></div><span class="radar-star">✦</span><div class="radar-point"></div><div class="radar-point two"></div></div></section>${metricCards()}<div class="two-col"><div><section class="panel"><div class="panel-header"><div><h2>On your radar</h2><p>Preference-based recommendations, with room for discovery.</p></div><a href="#discover" data-nav="discover">View all ${icon('arrow')}</a></div>${rec.length?`<div class="job-list">${rec.map(j=>jobCard(j)).join('')}</div>`:empty('discover','Let’s find your first opportunity.','Refresh the public career feeds to build your personal radar. Source failures will appear here, and no sample jobs will be added.',button(data.discovery.running?'Refresh in progress…':'Discover opportunities','refresh','primary','refresh'))}</section><section class="panel"><div class="panel-header"><div><h2>Application momentum</h2><p>Your last eight weeks, one move at a time.</p></div><span class="badge">8 weeks</span></div>${weeklyChart()}</section></div><aside class="right-column"><section class="panel"><div class="panel-header"><h2>Your pipeline</h2><span class="badge">${data.applications.length} total</span></div><div class="pipeline">${['Applied','In Review','Recruiter Contact','Interviewing','Assessment','Offer'].map(s=>`<div class="pipeline-row"><span class="status-dot ${statusClass(s)}"></span><span>${s}</span><b>${metrics().count(s)}</b></div>`).join('')}</div><hr class="section-divider"><a class="button small" href="#applications" data-nav="applications">Open application tracker ${icon('arrow')}</a></section><section class="panel"><div class="panel-header"><h2>Discovery pulse</h2><span class="badge ${data.discovery.running?'green':''}">${data.discovery.running?'Refreshing':'Source status'}</span></div>${sourcesPanel(4)}<div class="source-summary">Last successful source refresh: ${data.discovery.lastSuccessfulAt?formatDate(data.discovery.lastSuccessfulAt)+' · '+ago(data.discovery.lastSuccessfulAt):'Not yet'}</div></section><section class="panel"><div class="panel-header"><h2>A more personal match</h2>${icon('spark')}</div><p class="muted small">Your interests are the starting point. Scores stay provisional until your skills and experience can be reviewed.</p><div class="button-row" style="margin-top:15px"><a href="#profile" data-nav="profile" class="button small">Refine your profile ${icon('arrow')}</a></div></section></aside></div><p class="footer-note">Thoughtful recommendations. Real sources. Your judgment always comes first.</p>`;}
function sourcesPanel(max=99){return data.discovery.sources.slice(0,max).map(s=>`<div class="source-row"><span class="dot ${s.lastRun?.success?'ok':s.lastRun?'error':''}"></span><div class="source-info">${e(s.company)} <small>${e(s.kind)} · ${s.lastRun?.success?s.lastRun.count+' postings':s.lastRun?.error?.split(' · ')[0]??'Not refreshed'}</small></div><span class="badge ${s.lastRun?.success?'green':s.lastRun?'amber':''}">${s.lastRun?.success?'Synced':s.lastRun?'Retry needed':'Ready'}</span></div>`).join('');}
function weeklyChart(){const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7)-49);const weeks=Array.from({length:8},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i*7);const end=new Date(d);end.setDate(end.getDate()+7);return {date:d,count:data.applications.filter(a=>new Date(a.appliedAt+'T12:00:00')>=d&&new Date(a.appliedAt+'T12:00:00')<end).length};});const max=Math.max(1,...weeks.map(w=>w.count));return `<div class="chart" role="img" aria-label="Applications by week: ${weeks.map(w=>formatDate(w.date.toISOString())+': '+w.count).join('; ')}">${weeks.map(w=>`<div class="chart-col"><span>${w.count||''}</span><div class="bar" style="height:${Math.max(3,w.count/max*100)}px"></div></div>`).join('')}${!data.applications.length?'<div class="chart-empty">Your momentum starts with one application.</div>':''}</div><div class="chart-labels">${weeks.map(w=>`<span>${formatDate(w.date.toISOString())}</span>`).join('')}</div>`;}
function jobCard(j){const applied=data.applications.some(a=>a.jobId===j.id);const stale=Date.now()-Date.parse(j.verifiedAt)>48*3600000;return `<article class="job-card"><div class="job-top">${logo(j.company)}<div class="job-title"><h3><button class="link-button" data-action="job" data-id="${j.id}">${e(j.title)}</button></h3><div class="company-line">${e(j.company)} ${categoryBadge(j.match.category)}</div></div><div class="match-score" title="${e(j.match.basis??'Preference-based')} · provisional score">${j.match.score}<small>${j.match.resume?'résumé':'preference'}<br>match</small></div></div><div class="job-meta"><span>${icon('location')}${e(j.location)}</span><span>${icon('money')}${e(salary(j))}</span><span>${icon('applications')}${e(j.arrangement)}</span></div><p class="job-fit">${icon('spark')}${e(j.match.explanation)}</p><div class="posting-links"><a href="${e(j.url)}" class="button small" target="_blank" rel="noopener noreferrer">${icon('external')}Original posting</a><a href="${e(linkedInSearch(j))}" class="button small" target="_blank" rel="noopener noreferrer" title="Search LinkedIn for this title and company; an exact listing is not verified.">Search LinkedIn</a></div><div class="job-bottom"><div><span class="job-date">${j.postedAt?'Published '+formatDate(j.postedAt):'Posting date unavailable'} · ${j.availability==='Closed'?'Closed at source':stale?'Availability needs refresh':'Last seen open'}</span></div><div class="button-row"><button class="icon-button" data-action="save" data-id="${j.id}" aria-label="${j.saved?'Unsave':'Save'} ${e(j.title)}" aria-pressed="${j.saved}">${icon(j.saved?'check':'saved')}</button><button class="button small" data-action="job" data-id="${j.id}">${applied?'Tracked':'View role'} ${icon('arrow')}</button></div></div></article>`;}
function filteredJobs(){let jobs=data.jobs.filter(j=>route!=='saved'||j.saved).filter(j=>route!=='wildcards'||j.match.category==='Wildcard');if(tab!=='All')jobs=jobs.filter(j=>j.match.category===tab);jobs=jobs.filter(j=>(filters.dismissed||!j.dismissed)&&(filters.closed||j.availability==='Open')&&(!search||`${j.title} ${j.company} ${j.location}`.toLowerCase().includes(search.toLowerCase()))&&(!filters.company||j.company===filters.company)&&(!filters.location||j.location.toLowerCase().includes(filters.location.toLowerCase()))&&(filters.mode==='All'||j.arrangement===filters.mode)&&j.match.score>=Number(filters.score)&&(!filters.minSalary||(j.currency==='USD'&&(j.salaryMax??j.salaryMin)>=Number(filters.minSalary))||(filters.includeUnknown&&(j.salaryMax===null&&j.salaryMin===null||j.currency!=='USD')))&&(!filters.source||j.sources.some(s=>s.source.startsWith(filters.source+':')))&&(!filters.date||j.postedAt&&Date.parse(j.postedAt)>=Date.now()-Number(filters.date)*86400000));if(sort==='score')jobs.sort((a,b)=>b.match.score-a.match.score);if(sort==='newest')jobs.sort((a,b)=>Date.parse(b.postedAt??b.discoveredAt)-Date.parse(a.postedAt??a.discoveredAt));if(sort==='salary')jobs.sort((a,b)=>(b.currency==='USD'?(b.salaryMax??b.salaryMin??0):0)-(a.currency==='USD'?(a.salaryMax??a.salaryMin??0):0));return jobs;}
function option(v,label,current){return `<option value="${e(v)}" ${String(current)===String(v)?'selected':''}>${e(label)}</option>`;}
function jobResults(){const jobs=filteredJobs();return `<div class="results-line"><span>${jobs.length} opportunit${jobs.length===1?'y':'ies'}${data.totalIngested?' · '+data.totalIngested+' total postings ingested':''}</span><span>${data.matchingResume?'Résumé-informed':'Preference-based'} · provisional</span></div><div class="discover-grid">${jobs.length?jobs.slice(0,limit).map(j=>jobCard(j)).join(''):`<div class="panel wide-empty">${empty('discover',data.jobs.length?'No opportunities match these filters.':'Your radar is ready to begin.',data.jobs.length?'Try another search or reset your filters.':'Refresh the sources to discover real opportunities. If a feed is unavailable, its error will appear in Settings.',button(data.jobs.length?'Reset filters':'Refresh sources',data.jobs.length?'reset-filters':'refresh','primary',data.jobs.length?'filter':'refresh'))}</div>`}</div>${jobs.length>limit?button('Show more opportunities','load-more','load-more'):''}`;}
function discover(){const title=route==='saved'?'Worth coming back to.':route==='wildcards'?'A different kind of possibility.':'Find your next meaningful move.';return `${heading(route==='saved'?'YOUR SHORTLIST':route==='wildcards'?'THINK BEYOND THE TITLE':'PERSONAL OPPORTUNITY INTELLIGENCE',title,route==='saved'?'The opportunities you’ve saved, all in one place.':route==='wildcards'?'Unexpected paths connected by transferable skills and shared interests.':'Core alignment, adjacent paths, and a little serendipity.',button(data.discovery.running?'Refreshing…':'Refresh sources','refresh','','refresh'))}${route==='wildcards'?'<div class="notice">'+icon('spark')+'<div>Wildcards are explorations, not eligibility claims. Each role explains possible skill transfer and what still needs verification.</div></div>':''}${route!=='wildcards'?`<div class="tabs" role="tablist" aria-label="Discovery category">${['All','Core','Adjacent','Wildcard'].map(t=>`<button class="tab ${tab===t?'active':''}" role="tab" aria-selected="${tab===t}" data-action="tab" data-value="${t}">${t==='All'?'For you':t==='Core'?'Core matches':t==='Adjacent'?'Adjacent paths':'✦ Wildcards'} <small>${data.jobs.filter(j=>(route!=='saved'||j.saved)&&!j.dismissed&&j.availability==='Open'&&(t==='All'||j.match.category===t)).length}</small></button>`).join('')}</div>`:''}<div class="toolbar"><label class="search">${icon('search')}<input id="search-jobs" type="search" placeholder="Search roles, companies, or locations" aria-label="Search opportunities" value="${e(search)}"></label><select class="select" id="job-sort" aria-label="Sort opportunities">${option('recommended','Recommended mix',sort)}${option('score','Highest match',sort)}${option('newest','Newest first',sort)}${option('salary','Published USD salary',sort)}</select>${button('Filters','filters',advanced?'primary':'','filter')}</div>${advanced?`<div class="filter-panel"><div class="field"><label for="filter-company">Company</label><select id="filter-company" data-filter="company">${option('','All companies',filters.company)}${[...new Set(data.jobs.map(j=>j.company))].sort().map(v=>option(v,v,filters.company)).join('')}</select></div><div class="field"><label for="filter-location">Location contains</label><input id="filter-location" data-filter="location" value="${e(filters.location)}" placeholder="e.g. New York"></div><div class="field"><label for="filter-mode">Work arrangement</label><select id="filter-mode" data-filter="mode">${['All','Remote','Hybrid','On-site','Not specified'].map(v=>option(v,v,filters.mode)).join('')}</select></div><div class="field"><label for="filter-score">Minimum score</label><input id="filter-score" type="number" data-filter="score" min="0" max="100" value="${filters.score}"></div><div class="field"><label for="filter-salary">Minimum annual USD salary</label><input id="filter-salary" type="number" data-filter="minSalary" min="0" step="1000" value="${filters.minSalary}"></div><div class="field"><label for="filter-source">Source</label><select id="filter-source" data-filter="source">${['','greenhouse','lever','ashby'].map(v=>option(v,v||'All sources',filters.source)).join('')}</select></div><div class="field"><label for="filter-date">Publication date</label><select id="filter-date" data-filter="date">${[['','Any date'],['7','Last 7 days'],['30','Last 30 days'],['90','Last 90 days']].map(([v,l])=>option(v,l,filters.date)).join('')}</select></div><label class="checkbox"><input type="checkbox" data-filter="includeUnknown" ${filters.includeUnknown?'checked':''}>Include unknown salary</label><label class="checkbox"><input type="checkbox" data-filter="closed" ${filters.closed?'checked':''}>Include closed postings</label><label class="checkbox"><input type="checkbox" data-filter="dismissed" ${filters.dismissed?'checked':''}>Include dismissed roles</label>${button('Reset filters','reset-filters','small')}</div>`:''}<div id="job-results">${jobResults()}</div><p class="footer-note">Recommendation mix targets 60% Core · 25% Adjacent · 15% Wildcard when available. Roles are never invented to fill a quota.</p>`;}
function filteredApps(){let apps=data.applications.filter(a=>(appStatus==='All'||a.status===appStatus)&&(!search||Object.values(a).some(v=>typeof v==='string'&&v.toLowerCase().includes(search.toLowerCase())))&&Object.entries(appFilters).every(([k,v])=>!v||(k==='from'?a.appliedAt>=v:k==='to'?a.appliedAt<=v:String(a[k]??'').toLowerCase().includes(v.toLowerCase()))));if(appSort==='oldest')apps.sort((a,b)=>a.appliedAt.localeCompare(b.appliedAt));if(appSort==='company')apps.sort((a,b)=>a.company.localeCompare(b.company));if(appSort==='updated')apps.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return apps;}
function applicationTable(){const apps=filteredApps();if(!apps.length)return `<section class="panel">${empty('applications',data.applications.length?'No applications match these filters.':'One place for every next step.',data.applications.length?'Clear your search or choose another status.':'Add your first application manually. Track its progress, keep notes, and know when to follow up.',button('Add an application','add-app','primary','plus'))}</section>`;return `<div class="results-line"><span>${apps.length} application${apps.length===1?'':'s'}</span><span>Click a role to view or edit</span></div><div class="table-wrap"><table><thead><tr><th>COMPANY / ROLE</th><th>STATUS</th><th>APPLIED</th><th>LOCATION</th><th>SOURCE</th><th>LATEST UPDATE</th><th>CONTACT</th><th></th></tr></thead><tbody>${apps.map(a=>`<tr><td><div class="table-company">${logo(a.company)}<div class="table-title"><strong>${e(a.company)}</strong><button class="table-button" data-action="edit-app" data-id="${a.id}">${e(a.title)}</button></div></div></td><td>${badge(a.status)}</td><td>${formatDate(a.appliedAt)}</td><td>${e(a.location||'Not specified')}</td><td>${e(a.source)}</td><td><span>${e(a.summary? a.summary.slice(0,65)+(a.summary.length>65?'…':''):'No update recorded')}</span><br><small>${formatDate(a.updatedAt)}</small></td><td>${e(a.contact||'—')}</td><td><button class="icon-button" data-action="edit-app" data-id="${a.id}" aria-label="Edit ${e(a.company)} application">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function applications(){return `${heading('EVERY STEP, IN PERSPECTIVE','Your application journey.','From the first application to the right offer.',`<div class="button-row"><a class="button" href="/api/export?format=csv" download>${icon('download')}Export</a>${button('Add application','add-app','primary','plus')}</div>`)}${metricCards()}<div class="toolbar"><label class="search">${icon('search')}<input type="search" id="search-apps" placeholder="Search companies, roles, notes…" aria-label="Search applications" value="${e(search)}"></label><select class="select" id="app-status" aria-label="Filter by status">${option('All','All statuses',appStatus)}${statuses.map(s=>option(s,s,appStatus)).join('')}</select><select class="select" id="app-sort" aria-label="Sort applications">${[['newest','Newest applications'],['oldest','Oldest applications'],['company','Company A–Z'],['updated','Latest update']].map(([v,l])=>option(v,l,appSort)).join('')}</select>${button('Filters','filters',advanced?'primary':'','filter')}</div>${advanced?`<div class="filter-panel">${[['company','Company'],['location','Location'],['source','Source'],['from','Applied after'],['to','Applied before']].map(([key,label])=>`<div class="field"><label for="app-filter-${key}">${label}</label><input id="app-filter-${key}" data-app-filter="${key}" type="${['from','to'].includes(key)?'date':'text'}" value="${e(appFilters[key])}"></div>`).join('')}${button('Clear filters','reset-app-filters','small')}</div>`:''}<div id="application-results">${applicationTable()}</div><p class="footer-note">“No Response” means at least 30 days since applying with no recorded recruiting response. Editing a note does not reset that clock.</p>`;}
function insights(){const m=metrics();return `${heading('THE BIGGER PICTURE','Make sense of your momentum.','A clear view of what’s happening, grounded in your own data.')}${metricCards()}<div class="two-col"><div><section class="panel"><div class="panel-header"><h2>Applications per week</h2><span class="badge">8 weeks</span></div>${weeklyChart()}</section><section class="panel"><div class="panel-header"><h2>Recent activity</h2></div>${data.activity.length?data.activity.map(a=>`<div class="activity"><div class="activity-icon">${icon(a.kind==='preferences'?'profile':'applications')}</div><div><p>${e(a.summary)}</p><small>${ago(a.createdAt)}</small></div></div>`).join(''):empty('clock','A story in the making.','Application and preference updates will appear here.','',true)}</section></div><aside><section class="panel"><div class="panel-header"><h2>Application outcomes</h2></div><div class="pipeline">${statuses.map(s=>`<div class="pipeline-row"><span class="status-dot ${statusClass(s)}"></span>${s}<b>${m.count(s)}</b></div>`).join('')}</div></section><section class="panel"><div class="panel-header"><h2>How metrics are calculated</h2>${icon('info')}</div><p class="small muted">Response rate is applications with a recorded recruiting response divided by total applications. Interviewing counts active interview processes; it does not estimate past interviews.</p><hr class="section-divider"><p class="small muted">Unknown data stays unknown. No benchmark or trend is inferred from an empty history.</p></section></aside></div>`;}
function profile(){const p=data.profile.preferences;return `${heading('BUILT AROUND YOU','The work you want. The life you want.','Use a reviewed résumé as your foundation. Preferences guide where you want to go.')}${resumeSection(libraryContext())}<form id="profile-form"><div class="profile-grid"><div><section class="panel"><div class="panel-header"><div><h2>Your career compass</h2><p>Separate each interest, location, or employer with a comma.</p></div>${icon('discover')}</div><div class="form-grid"><div class="field wide"><label for="interests">Career interests</label><textarea id="interests" name="interests" rows="4" required>${e(p.interests.join(', '))}</textarea></div><div class="field wide"><label for="industries">Preferred industries</label><textarea id="industries" name="industries" rows="2">${e(p.industries.join(', '))}</textarea></div><div class="field wide"><label for="employers">Employers of interest</label><textarea id="employers" name="employers" rows="2">${e(p.employers.join(', '))}</textarea><small>Preferences, never an exclusive list.</small></div><div class="field wide"><label for="locations">Preferred locations</label><input id="locations" name="locations" value="${e(p.locations.join(', '))}" required></div><div class="field"><label for="minSalary">Preferred minimum base salary (USD / year)</label><input id="minSalary" type="number" name="minSalary" min="0" max="1000000" step="1000" value="${p.minSalary}" required></div><div class="field"><label class="checkbox" style="margin-top:30px"><input name="remotePreferred" type="checkbox" ${p.remotePreferred?'checked':''}>Prefer remote and hybrid roles</label></div><div class="field wide"><label for="constraints">Seniority, interests, and other context</label><textarea id="constraints" name="constraints">${e(p.constraints)}</textarea><small>Stored for your reference; free-text constraints do not automatically exclude jobs.</small></div></div></section><section class="panel"><div class="panel-header"><div><h2>Skills you can stand behind</h2><p>Add only skills you actually have. These remain self-reported.</p></div>${icon('shield')}</div><div class="field"><label for="verifiedSkills">Your skills, separated by commas</label><textarea id="verifiedSkills" name="verifiedSkills" placeholder="e.g. Open-source research, Interviewing, SQL">${e(p.verifiedSkills.join(', '))}</textarea><small>Career interests are never treated as evidence of experience.</small></div></section></div><aside><section class="panel"><div class="panel-header"><h2>What matters most</h2><span class="badge">Configurable</span></div>${Object.entries(p.weights).map(([k,v])=>`<label class="weight-row"><span>${({role:'Role & responsibilities',skills:'Skills & experience',industry:'Industry & employer',compensation:'Compensation',location:'Location & arrangement',seniority:'Seniority'})[k]}</span><input name="weight-${k}" data-weight type="number" min="0" max="100" value="${v}" aria-label="${e(k)} weight percent" required></label>`).join('')}<div class="weight-total"><span>Total weight</span><strong id="weight-total">100%</strong></div></section><section class="panel"><div class="panel-header"><h2>Your matching foundation</h2>${icon('file')}</div><span class="badge ${data.matchingResume?'green':'amber'}">${data.matchingResume?'Reviewed résumé':'Preferences only'}</span><p class="small muted" style="margin-top:13px">${data.matchingResume?e(data.matchingResume.title):'Add and review a résumé above, then select it for matching. No qualifications are invented while your résumé is awaiting review.'}</p></section><div class="notice">${icon('info')}<div>All scores are provisional. Saving preferences recalculates the current feed automatically.</div></div></aside></div><p class="form-error" role="alert"></p><div class="button-row"><button type="submit" class="button primary">${icon('check')}Save & recalculate matches</button></div></form>`;}
function settings(){return `${heading('YOUR WORKSPACE CONNECTION','Ready for the next step.','The interface is on GitHub Pages. Your private backend is still separate.')}<section class="panel preview-connection"><span class="badge amber">Backend not connected</span><h2>A public interface. A private workspace.</h2><p>You can explore every section and try the application form with sample information. Preview changes live only in this tab and reset when you reload. No account is signed in and no personal records are loaded.</p><p>Durable records, authentication, job refresh, Gmail, and document uploads require the hosted private backend. Those services are not connected here yet.</p><p>Your existing local database and documents remain untouched. Do not enter private information in the preview.</p><a class="button" href="https://github.com/libbyix9-blip/jobtrackerrrr" target="_blank" rel="noopener noreferrer">View source &amp; deployment history ↗</a></section>`;}

function showModal(title,subtitle,content){modal.innerHTML=`<header class="modal-head"><div><h2 id="modal-title">${e(title)}</h2>${subtitle?`<p>${e(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${content}</div>`;if(!modal.open)modal.showModal();}
async function showJob(id){showModal('Opening opportunity…','','<div class="skeleton"></div>');try{const j=await api('jobs/'+id),m=j.match,applied=data.applications.some(a=>a.jobId===id);showModal(j.title,j.company+' · '+j.location,`<div class="button-row">${categoryBadge(m.category)}<span class="badge green">${m.score}/100 · ${e(m.classification)}</span><span class="badge">${e(m.basis??'Preference-based')} · provisional score</span><span class="badge">${e(j.arrangement)}</span></div><h3>Why it’s on your radar</h3><p>${e(m.explanation)}</p>${m.category==='Wildcard'?`<h3>What makes it interesting</h3><p>${e(m.interesting)}</p><h3>Possible transferable skills</h3><p>${e(m.transferable)}</p><h3>Realistic fit or stretch?</h3><p>${e(m.realism)}</p>`:''}<h3>What still needs verification</h3><ul>${m.missing.map(s=>`<li>${e(s)}</li>`).join('')}</ul>${m.knownSkills.length?`<h3>Supported skills mentioned in this posting</h3><p>${e(m.knownSkills.join(', '))}. Source: ${m.resume?'your reviewed résumé and profile':'your profile'}. This does not verify depth or years of experience.</p>`:''}${m.resume?`<h3>Résumé foundation: ${e(m.resume.title)}</h3>${m.resume.evidence.length?`<ul>${m.resume.evidence.map(line=>`<li>${e(line)}</li>`).join('')}</ul>`:'<p>No direct reviewed skill evidence overlaps with this posting.</p>'}`:''}<h3>The score, explained</h3><div class="score-breakdown">${Object.entries(m.components).map(([k,v])=>`<div class="score-component"><span>${e(k[0].toUpperCase()+k.slice(1))} (${data.profile.preferences.weights[k]}%)</span><progress value="${v}" max="100" aria-label="${e(k)} component"></progress><span>${v}/100</span></div>`).join('')}</div><p style="margin-top:10px;font-size:10px">Skills without evidence and unknown salaries receive a neutral score of 50. Remote location eligibility still needs verification. ${m.feedbackAdjustment?'Your feedback adjusted the role component by '+m.feedbackAdjustment+' points.':''}</p><h3>Compensation</h3><p>${e(salary(j))}${j.salaryText?'<br>'+e(j.salaryText):''}</p>${m.caveats.length?`<ul>${m.caveats.map(v=>`<li>${e(v)}</li>`).join('')}</ul>`:''}<h3>Responsibilities & full posting</h3><div class="description">${e(j.description||'Description unavailable. Read the original posting for requirements and responsibilities.')}</div>${j.qualifications?'<h3>Published qualifications</h3><div class="description">'+e(j.qualifications)+'</div>':'<p style="margin-top:10px">Qualifications are not separately structured by this source. Review them in the full description and original posting.</p>'}${letterSuggestions(j.letterSuggestions,id,libraryContext())}<h3>Source & availability</h3><p>${e(j.sources.map(s=>s.source).join(', '))}<br>Discovered ${formatDate(j.discoveredAt)} · Last verified ${formatDate(j.verifiedAt,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}<br>${j.availability==='Open'?'Last seen open at the source. Availability can change.':'Closed on the latest successful source refresh.'}</p><div class="button-row" style="margin-top:16px">${button(j.feedback==='More like this'?'✓ More like this':'More like this','more-like','small','thumb').replace('data-action="more-like"',`data-action="more-like" data-id="${id}"`)}${button(j.dismissed?'Restore opportunity':'Not interested','dismiss','small').replace('data-action="dismiss"',`data-action="dismiss" data-id="${id}"`)}${button(j.saved?'Saved':'Save opportunity','save','small','saved').replace('data-action="save"',`data-action="save" data-id="${id}"`)}</div><div class="posting-links">${originalPostingLinks(j)}<a class="button small" href="${e(linkedInSearch(j))}" target="_blank" rel="noopener noreferrer">Search LinkedIn ${icon('external')}</a></div><div class="modal-footer"><a class="button primary" href="${e(j.url)}" target="_blank" rel="noopener noreferrer">Original posting ${icon('external')}</a><button class="button" data-action="mark-applied" data-id="${id}" ${applied?'disabled':''}>${applied?'Already in your tracker':'I applied · add to tracker'}</button></div><p style="font-size:10px;margin-top:11px">Marking applied only creates a tracking record. CareerOS does not submit an application.</p>`);}catch(err){showModal('Couldn’t open this role','',`<p>${e(err.message)}</p>`);}}
function applicationForm(id=null){const a=data.applications.find(x=>x.id===id)??{company:'',title:'',status:'Applied',appliedAt:new Date().toISOString().slice(0,10),source:'Manual',location:'',contact:'',summary:'',notes:'',url:'',lastResponseAt:''};showModal(id?'Application details':'A new step forward',id?a.company+' · '+a.title:'Keep the details. Make the next step easier.',`<form id="application-form" data-id="${id??''}"><div class="form-grid">${[['company','Company',true],['title','Job title',true],['location','Location / remote status',false],['source','Application source',true]].map(([name,label,required])=>`<div class="field"><label for="application-${name}">${label}</label><input id="application-${name}" name="${name}" value="${e(a[name])}" maxlength="250" ${required?'required':''}></div>`).join('')}<div class="field"><label for="application-date">Application date</label><input id="application-date" name="appliedAt" type="date" value="${e(a.appliedAt)}" max="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label for="application-status">Current status</label><select id="application-status" name="status">${statuses.map(s=>option(s,s,a.status)).join('')}</select></div><div class="field"><label for="application-contact">Recruiter or contact</label><input id="application-contact" name="contact" maxlength="300" value="${e(a.contact)}"></div><div class="field"><label for="application-response">Last recruiting response date</label><input id="application-response" name="lastResponseAt" type="date" max="${new Date().toISOString().slice(0,10)}" value="${e(a.lastResponseAt??'')}"><small>Leave empty if there has been no response.</small></div><div class="field wide"><label for="application-url">Original posting URL</label><input id="application-url" name="url" type="url" value="${e(a.url)}" placeholder="https://…"></div><div class="field wide"><label for="application-summary">Latest update summary</label><textarea id="application-summary" name="summary" maxlength="2000">${e(a.summary)}</textarea></div><div class="field wide"><label for="application-notes">Your notes</label><textarea id="application-notes" name="notes" maxlength="10000" rows="4" placeholder="People, preparation, and things to remember…">${e(a.notes)}</textarea></div></div>${id?`<p class="small muted" style="margin-top:16px">Last updated ${formatDate(a.updatedAt)} · Manual record · Classification confidence: not applicable</p>`:''}<p class="form-error" role="alert"></p><div class="modal-footer"><div>${id?`<button type="button" class="button danger small" data-action="delete-app" data-id="${id}">Remove application</button>`:''}</div><button class="button primary" type="submit">${icon('check')}${id?'Save changes':'Add application'}</button></div></form>`);}
async function refresh(){if(data.discovery.running)return toast('Discovery is already refreshing.');try{await api('refresh','POST',{});toast('Refreshing public ATS feeds. Source status will update here.');await load();}catch(err){toast(err.message,true);}}
async function updateJob(id,patch,message){await api('jobs/'+id+'/state','PATCH',patch);await load();toast(message);}
async function action(name,target){
 const id=target.dataset.id;
 if(await gmailAction(name,target,libraryContext()))return;
 if(await libraryAction(name,target,libraryContext()))return;
 if(name==='retry')return init();if(name==='close-modal')return modal.close();
 if(name==='theme'){theme=theme==='light'?'dark':'light';localStorage.setItem('careeros-theme',theme);document.documentElement.dataset.theme=theme;return data?renderApp():renderAuth();}
 if(name==='menu'){$('.sidebar')?.classList.toggle('open');$('.mobile-overlay')?.classList.toggle('open');return;}
 if(name==='logout'){await api('logout','POST',{});data=null;session=null;return init();}
 if(name==='search'){navigate('discover');return $('#search-jobs')?.focus();}
 if(name==='refresh')return refresh();
 if(name==='filters'){advanced=!advanced;return renderApp();}
 if(name==='tab'){tab=target.dataset.value;limit=24;return renderApp();}
 if(name==='job')return showJob(id);
 if(name==='save'){const j=data.jobs.find(j=>j.id===id);await updateJob(id,{saved:!j.saved},j.saved?'Removed from saved jobs.':'Saved to your shortlist.');if(modal.open)return showJob(id);return;}
 if(name==='more-like'){await updateJob(id,{feedback:'More like this'},'Feedback saved. Related role scores have been updated.');return showJob(id);}
 if(name==='dismiss'){const j=data.jobs.find(j=>j.id===id);await updateJob(id,{dismissed:!j.dismissed,feedback:j.dismissed?null:'Not interested'},j.dismissed?'Opportunity restored.':'Dismissed. Your feedback will inform related matches.');return modal.close();}
 if(name==='mark-applied'){await api('jobs/'+id+'/applied','POST',{});await load();modal.close();toast('Added to your tracker. No application was sent.');return;}
 if(name==='add-app')return applicationForm();if(name==='edit-app')return applicationForm(id);
 if(name==='delete-app'){if(!confirm('Remove this application and its notes?'))return;await api('applications/'+id,'DELETE');modal.close();await load();return toast('Application removed.');}
 if(name==='load-more'){limit+=24;$('#job-results').innerHTML=jobResults();return;}
 if(name==='reset-filters'){filters={company:'',location:'',mode:'All',score:0,minSalary:0,includeUnknown:true,closed:false,dismissed:false,source:'',date:''};search='';tab='All';return renderApp();}
 if(name==='reset-app-filters'){appFilters={company:'',location:'',source:'',from:'',to:''};search='';appStatus='All';return renderApp();}
 if(name==='delete-account')return showModal('Delete your personal workspace?','This removes your account and all personal records.',`<p>Public job postings and source refresh logs remain. Database backups must be removed separately. This cannot be undone in the app.</p><form id="delete-account-form"><div class="field" style="margin-top:20px"><label for="confirm-email">Type ${e(data.profile.email)} to confirm</label><input id="confirm-email" type="email" name="confirm" required autocomplete="off"></div><p class="form-error" role="alert"></p><div class="modal-footer"><button type="button" class="button" data-action="close-modal">Keep my workspace</button><button type="submit" class="button danger">Delete my account</button></div></form>`);
}
for(const el of [root,modal])el.addEventListener('click',async event=>{
 const link=event.target.closest('[data-nav]');if(link){event.preventDefault();if(modal.open)modal.close();navigate(link.dataset.nav);return;}
 const target=event.target.closest('[data-action]');if(!target)return;
 const wasDisabled=target.disabled;if(wasDisabled)return;target.disabled=true;
 try{await action(target.dataset.action,target);}catch(err){toast(err.message,true);}finally{target.disabled=false;}
});
root.addEventListener('input',event=>{
 const target=event.target;
 if(libraryInput(target,libraryContext()))return;
 if(target.id==='search-jobs'){search=target.value;limit=24;$('#job-results').innerHTML=jobResults();}
 if(target.id==='search-apps'){search=target.value;$('#application-results').innerHTML=applicationTable();}
 if(target.dataset.filter){filters[target.dataset.filter]=target.type==='checkbox'?target.checked:target.value;$('#job-results').innerHTML=jobResults();}
 if(target.dataset.appFilter){appFilters[target.dataset.appFilter]=target.value;$('#application-results').innerHTML=applicationTable();}
 if(target.hasAttribute('data-weight')){$('#weight-total').textContent=[...document.querySelectorAll('[data-weight]')].reduce((n,i)=>n+Number(i.value),0)+'%';}
});
root.addEventListener('change',event=>{const t=event.target;if(t.dataset.documentUpload){uploadFiles(t.files,t.dataset.documentUpload,libraryContext()).catch(err=>toast(err.message,true));t.value='';return;}if(gmailInput(t,libraryContext()))return;if(libraryInput(t,libraryContext()))return;if(t.id==='job-sort'){sort=t.value;$('#job-results').innerHTML=jobResults();}if(t.id==='app-status'){appStatus=t.value;$('#application-results').innerHTML=applicationTable();}if(t.id==='app-sort'){appSort=t.value;$('#application-results').innerHTML=applicationTable();}});
async function submit(event){
 const form=event.target;if(form.id==='gmail-review-form'){event.preventDefault();await gmailSubmit(form,libraryContext());return;}if(form.id==='document-form'){event.preventDefault();await librarySubmit(form,libraryContext());return;}if(!['auth-form','application-form','profile-form','delete-account-form'].includes(form.id))return;event.preventDefault();const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');error.textContent='';submit.disabled=true;
 try{
  const fields=Object.fromEntries(new FormData(form));
  if(form.id==='auth-form'){await api(form.dataset.setup==='true'?'setup':'login','POST',fields);document.addEventListener('click',event=>{const link=event.target.closest?.('a[href^="/api/"]');if(!link)return;event.preventDefault();if(link.getAttribute('href').startsWith('/api/export')){const csv=link.getAttribute('href').includes('csv');const blob=new Blob([exportPreview(csv)],{type:csv?'text/csv;charset=utf-8':'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=csv?'careeros-preview.csv':'careeros-preview.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else toast('Document downloads require the private backend.',true);});
await init();
window.addEventListener('hashchange',()=>{if(data){route=location.hash.slice(1)||'overview';renderApp();}});}
  if(form.id==='application-form'){await api('applications'+(form.dataset.id?'/'+form.dataset.id:''),form.dataset.id?'PUT':'POST',fields);modal.close();await load();toast('Application saved.');}
  if(form.id==='profile-form'){
   const list=k=>String(fields[k]).split(',').map(v=>v.trim()).filter(Boolean);const weights={};for(const k of Object.keys(data.profile.preferences.weights))weights[k]=Number(fields['weight-'+k]);
   const preferences={interests:list('interests'),industries:list('industries'),employers:list('employers'),locations:list('locations'),verifiedSkills:list('verifiedSkills'),minSalary:Number(fields.minSalary),remotePreferred:fields.remotePreferred==='on',constraints:fields.constraints,weights};
   await api('preferences','PUT',preferences);await load();toast('Profile saved. Your matches have been recalculated.');
  }
  if(form.id==='delete-account-form'){await api('account','DELETE',fields);modal.close();data=null;session=null;document.addEventListener('click',event=>{const link=event.target.closest?.('a[href^="/api/"]');if(!link)return;event.preventDefault();if(link.getAttribute('href').startsWith('/api/export')){const csv=link.getAttribute('href').includes('csv');const blob=new Blob([exportPreview(csv)],{type:csv?'text/csv;charset=utf-8':'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=csv?'careeros-preview.csv':'careeros-preview.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else toast('Document downloads require the private backend.',true);});
await init();
window.addEventListener('hashchange',()=>{if(data){route=location.hash.slice(1)||'overview';renderApp();}});toast('Your account and personal records have been deleted.');}
 }catch(err){error.textContent=err.message;}finally{submit.disabled=false;}
}
root.addEventListener('submit',submit);modal.addEventListener('submit',submit);modal.addEventListener('change',event=>gmailInput(event.target,libraryContext()));
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
window.addEventListener('popstate',()=>{route=location.hash.slice(1)||'overview';if(data)renderApp();});

function libraryContext(){return {data,getData:()=>data,e,icon,heading,button,empty,api,load,toast,showModal,modal,statuses};}
function linkedInSearch(job){return 'https://www.linkedin.com/jobs/search/?keywords='+encodeURIComponent(job.title+' '+job.company);}
function originalPostingLinks(job){const seen=new Set();return (job.sources?.length?job.sources:[{url:job.url,source:'Original'}]).filter(s=>{if(seen.has(s.url))return false;seen.add(s.url);return true;}).map(s=>{let label=s.source?.split(':')[0]??'Source';try{const host=new URL(s.url).hostname;if(host==='linkedin.com'||host.endsWith('.linkedin.com'))label='LinkedIn';}catch{}return '<a class="button small" target="_blank" rel="noopener noreferrer" href="'+e(s.url)+'">View on '+e(label)+' '+icon('external')+'</a>';}).join('');}

document.addEventListener('click',event=>{const link=event.target.closest?.('a[href^="/api/"]');if(!link)return;event.preventDefault();if(link.getAttribute('href').startsWith('/api/export')){const csv=link.getAttribute('href').includes('csv');const blob=new Blob([exportPreview(csv)],{type:csv?'text/csv;charset=utf-8':'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=csv?'careeros-preview.csv':'careeros-preview.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else toast('Document downloads require the private backend.',true);});
await init();
window.addEventListener('hashchange',()=>{if(data){route=location.hash.slice(1)||'overview';renderApp();}});
